INSERT INTO plugin_cms_article ("category_id", "title", "subtitle", "slug", "summary", "cover", "author", "source", "content", "tags", "keywords", "description", "sort", "status", "is_top", "is_recommend", "views", "published_at", "created_at", "updated_at") VALUES
((SELECT "id" FROM plugin_cms_category WHERE "code"='1'), '公司简介', '', 'cms-1', 'LinaPro CMS是全新内核且永久开源免费的PHP企业网站开发建设管理系统，是一套高效、简洁、 强悍的可免费商用的PHP CMS源码，能够满足各类企业网站开发建设的需要。系统采用简单到想哭的模板标签，只要懂HTML就可快速开发企业网站。官方提供了大量网站模板免费下载和使用，将致力于为广大开发者和企', '', 'admin', '本站', '&lt;p&gt;&lt;span style=&quot;box-sizing: border-box; color: #333333; background-color: #FFFFFF; font-family: SimSun; font-size: 18px;&quot;&gt;温州鞋革产业研究院成立于&lt;/span&gt;&lt;span style=&quot;box-sizing: border-box; color: #333333; background-color: #FFFFFF; font-family: SimSun; font-size: 18px;&quot;&gt;2020年，是在温州市委市政府的支持和推动下，由鹿城区人民政府联合四川大学皮革化学与工程教育部重点实验室（全国唯一）、轻工科学与工程学院共建的创新型研究机构。2024年，为了进一步深化研究院与高等学府的产学研合作，由鹿城区人民政府与四川大学制革清洁技术国家工程实验室共建“四川大学 新材料与数字时尚温州创新中心”及“四川大学 科技成果转化温州中心”，以更加宽广的视野和更加深度的合作，持续推进研究院的建设与发展。研究院始终坚持“科技创新 时尚引领 产业升级”的战略&lt;/span&gt;&lt;span style=&quot;box-sizing: border-box; color: #333333; background-color: #FFFFFF; font-family: SimSun; font-size: 18px;&quot;&gt;方&lt;/span&gt;&lt;span style=&quot;box-sizing: border-box; color: #333333; background-color: #FFFFFF; font-family: SimSun; font-size: 18px;&quot;&gt;针，依托四川大学优势学科及资源，致力于打造&lt;/span&gt;&lt;span style=&quot;box-sizing: border-box; color: #333333; background-color: #FFFFFF; font-family: SimSun; font-size: 18px;&quot;&gt;“具有世界影响&lt;/span&gt;&lt;span style=&quot;box-sizing: border-box; color: #333333; background-color: #FFFFFF; font-family: SimSun; font-size: 18px;&quot;&gt;力的鞋业科创高&lt;/span&gt;&lt;span style=&quot;box-sizing: border-box; color: #333333; background-color: #FFFFFF; font-family: SimSun; font-size: 18px;&quot;&gt;地&lt;/span&gt;&lt;span style=&quot;box-sizing: border-box; color: #333333; background-color: #FFFFFF; font-family: SimSun; font-size: 18px;&quot;&gt;”。&lt;/span&gt;&lt;/p&gt;', '', '', 'LinaPro CMS是全新内核且永久开源免费的PHP企业网站开发建设管理系统，是一套高效、简洁、 强悍的可免费商用的PHP CMS源码，能够满足各类企业网站开发建设的需要。系统采用简单到想哭的模板标签，只要懂HTML就可快速开发企业网站。官方提供了大量网站模板免费下载和使用，将致力于为广大开发者和企', 255, 1, 0, 0, 61, '2018-04-11 17:26:11', '2018-04-11 17:26:11', '2026-04-18 21:57:09'),
((SELECT "id" FROM plugin_cms_category WHERE "code"='4'), '华为云：打造游戏创新智能世界的“黑土地”', '', 'cms-5', '', '', 'admin', '本站', '<p style="text-indent: 2em; text-align: left;">【<strong>PConline资讯</strong>】2018年4月2日，在GMGC北京2018第七届全球游戏大会现场，记者有幸采访到了华为消费互联网解决方案总经理聂颂，他分享了游戏行业创新发展的技术基石，以及作为游戏创新要素的AI、5G、区块链等技术会为创新者带来哪些价值。</p><p style="text-indent: 2em; text-align: center;">华为消费互联网解决方案总经理聂颂</p><p style="text-indent: 2em; text-align: left;">对于游戏创新，聂颂特别强调了技术这块“黑土地”的重要性：单机版扫雷游戏盛行的背后是IntelCPU和Windows操作系统的支撑；PC互联、线下支付以及IDC技术的成熟让游戏“传奇”的时代来临；2017年中国游戏2189亿人民币收入的背后，是4G、Wifi网络、移动支付、智能手机和<span class="hrefStyle">云计算</span>的成熟。而2018年，5G、区块链、AI、AR／VR的普及会给游戏行业带来玩法、服务以及场景上的多维度创新。</p><p style="text-indent: 2em; text-align: left;">对此，聂颂首先表示，在游戏解决方案上，<span class="hrefStyle">华为云</span>不做游戏产品，不与游戏企业争利，坚持做游戏企业的发动机和生产力。华为云游戏解决方案目前已经构建了游戏研发、游戏部署、游戏运营、游戏创新等全产业链条的能力。未来华为云将在游戏行业发力的几大方向：</p><p style="text-indent: 2em; text-align: left;">第一，是基础设施层面，过去几年游戏行业使用最多的产品是云主机虚拟机，华为云主机的性能优异，裸金属服务被第三方机构评为年度影响力产品。</p><p style="text-indent: 2em; text-align: left;">第二，是云容器产品方面，由于容器对于游戏部署来说意义重大，能够支撑游戏产品架构的演进。游戏企业通过使用容器，服务器部署的弹性速度提高10倍以上，并将扩展区服的时间降低到分钟级，整个运营成本降低超过50％。</p><p style="text-indent: 2em; text-align: left;">第三，在AI能力层面，华为作为业界在“云＋终”端同时具有芯片级别研发的公司，在终端侧，可以进行人脸识别；在云端可以进行大数据分析、视频分析、视觉认知；在架构底层，华为云使用了Atlas、GPU、FPGA等硬件为AI定制算力，从而可以在性能、延迟等方面满足游戏公司的需求。</p><p style="text-indent: 2em; text-align: left;">第四，华为的云游戏实现了即看即玩。游戏免修改、多个用户一起玩直播的游戏社交游戏让客户体验大幅提升。</p><p style="text-indent: 2em; text-align: left;">第五，在区块链层面，华为在十分钟之内就可以部署完整的区块链系统，每秒运算能力高达2000TPS，轻松帮助游戏客户实现不同游戏道具类的自由交换。</p><p style="text-indent: 2em; text-align: left;">最后，聂颂特别强调了华为终端的优势：超过3亿的注册手机用户，华为开发者联盟超过37万的用户，应用市场下载量450亿＋以及华为云100＋的服务。在此次大会上，华为还发布了与消费者云的端云联合计划，已注册认证的消费者云开发者可以获得端云协同大礼包，后续针对开发者创新等，华为云也会陆续推出更大更好的扶持计划。</p><p>随着游戏用户规模逐渐从增量市场转向存量市场，游戏市场正从买量用户数转向追求极致体验，以华为打造智能世界的“黑土地”为沃土，2018年中国游戏市场创新会有哪些改变，让我们拭目以待！</p><p><br/></p><p><br/></p>', '', '', '', 255, 1, 0, 0, 4, '2018-04-12 09:52:36', '2018-04-12 10:06:15', '2018-04-13 09:36:44'),
((SELECT "id" FROM plugin_cms_category WHERE "code"='4'), '锤子6年了 我们找到了它没有死的秘密', '', 'cms-6', '', '', 'admin', '本站', '<p>他有些戏谑意味地取了“锤子”这个名字。此前抡锤砸西门子冰箱的“壮举”让他一举成名，他想在手机圈里也搞出类似的动静来。这似乎预兆了他此后几年的命运：刺激。</p><p>另一个预兆发生在那年夏天。锤子办公室从中关村搬去望京，装车时突然电闪雷鸣暴雨如注。罗永浩站在旧办公室的窗边，念叨着“好了好了，我都知道了”，没多久，雷声停了雨也小了，似乎是天气与他达成了和解。</p><p><strong>“和解”是老罗锤子六年的另一个主题。从某种程度上说，这是他得以从手机死亡谷幸存的秘诀，但所有的得到都有代价，老罗祭出的牺牲品之一，就是曾经那个“罗永浩可爱多”。</strong></p><p><strong>壹</strong></p><p>锤子4月9日在北工大举办的发布会没有形成刷屏之势。</p><p>有锤粉觉得意外，场内人看来却是正常。<strong>除了性价比，当天发布的坚果3实在乏善可陈，就连素来精彩的老罗演讲，也如同这个季节开败了的玉兰花，蔫蔫的让人打不起精神。散场之后，有锤粉在微信群里讨论，比刚才谁睡着的时间更长。</strong></p><p>罗永浩选择了“怼”。发布会结束他就发了条微博：“回来看了一下网上的反馈，很多用翔的人都说丑，嗯，肯定会卖得很好，放心睡了。”第二天他又在微信公众号里称，那些骂坚果3丑的人是笨蛋。</p><p>依然是天生骄傲的语气，但配方似乎与6年前已经不一样了。</p><p>那时他讨伐的对象是小米。2012年是小米模式突飞猛进备受赞誉的一年，截至11月底，小米销售额已经突破100亿人民币——华为和酷派实现这个数字都花了6年，而此时距离雷军喝下那碗小米汤不过短短2年。</p><p>但罗永浩不服。</p><p>他很快展示他过人的毒舌功力，嘲讽小米是“手机期货”、“耍猴式营销”……他甚至为自己的犀利洋洋得意，“雷军确实被我们逼得重视设计和假装有人文情怀了”。</p><p>但出来混总是要还的，“产能”在此后几年成为罗永浩的紧箍咒，感受到切肤之痛后，他向雷军转达了歉意、感慨做产品不容易。</p><p>不过那都是后话了，回到2012年，毫无疑问，罗永浩赶上了智能手机的大风口。</p><p>热潮之中，很多巨变已经初见端倪。</p><p>小米自然是最炙手可热的明星，锤子就直接复制了它的早期模式：先做ROM再做手机。更多的大厂商还没反应过来，华为要在2013年才推出互联网品牌“荣耀”，魅族要在更晚的2014年才有“魅蓝”，至于联想的ZUK，那就是2015年迟到的故事了。</p><p>更多关于颠覆的故事在苹果之外的手机厂商间上演：</p><p>诺基亚连续14年手机老大的位置被三星替代，铁娘子王雪红带领HTC完成精品战略转型，坐上手机老二的位置。黑莓生厂商RIM
 选择了一条危险的道路：黑莓10成为放手一搏的产品，但它从2012年拖到2013年才面世，不情不愿发布触屏版的同时，还傲娇地保留了物理键盘板。</p><p>当时RIM还是很乐观的。时任CEO托斯滕·海因斯在谈及诺基亚的衰落时曾说，“我们现在拥有大约8000万名用户——这是诺基亚所不具备的。”但现实却是，尽管黑莓手机有奥巴马、Lady
 Gaga等一众粉丝，但随着黑莓公司在今年愚人节关闭BB OS 服务，最终，黑莓与诺基亚一样，把辉煌留给了历史。</p><p>风起云涌间，罗永浩掀起的波澜似乎多少带着点玩闹的成分。本来就有很多人抱着看笑话的心态，准备围观这位相声演员、英语老师如何玩砸，偏偏老罗还献上了料：</p><p>原先定在2012年年底发布的ROM跳票到次年3月，又因为工程师严重不足导致很多功能无法实现，加上发布会现场拖堂严重、网络瘫痪等原因，总之，那成为一场堪称“糟糕”的亮相，网络里几乎全是骂声。</p><p>有媒体称，那晚罗永浩失眠了，第二天，他在微博里亦保持了沉寂。</p><p><strong>贰</strong></p><p>做锤子的前几年，罗永浩一直没能甩掉“不靠谱”的标签。</p><p>他狂妄。在手机影子都没有的2013年，他就在微博发布文章：《为什么看起来只有锤子科技最可能成为下一个索尼(盛田时代的索尼)或下一个苹果(乔布斯时代的苹果)？》——而那一年，国内手机市场最活跃的角色是799元的红米手机，它直接拉动了小米销量，当年“双十一”，小米三分钟售出一亿元。</p><p>他随性，即使在投资人面前也不改本色。“他甚至聊一聊，就看手机，不搭理投资人”，媒体人黄章晋曾经这样评价。在演讲台上口舌生莲的罗永浩，其实有点社交恐惧症，谈合作时不知道怎么说半真半假的话。</p><p><strong>2013年那场“糟糕”的ROM发布会没多久，罗永浩就烧光了陌陌唐岩给的900万。他第一次面临钱的难题。但很多投资人对这位曾经怒砸冰箱的狂人有所忌讳，一位知名基金的风投曾表示，“我非常欣赏老罗”，但他转头告诉同事的却是：“我们是一分钱也不会给他的。”</strong></p><p>锤子在生产线上遇到的麻烦，狠狠给了罗永浩一“锤子”。</p><p>2014年5月，锤子T1 发布。对于从未涉足过硬件生产的罗永浩，这无疑是历史性的一步。在产品宣传图里，他高调称之为“东半球最好用的智能手机”。或许是担心触及新的《广告法》条例，没多久，宣传语又变成了“全球第二好用的智能手机”。</p><p>那场发布会上，罗永浩扬眉吐气，挺直了腰板，痛快嘲笑着整个手机行业，尽管T1首发只有3G版。</p><p>供应链反手给了他一巴掌。由于良品率过低等原因——有媒体援引业内人士的判断，锤子手机良品率不会超过50%，而正常数值应该在93%以上——T1 在发布后的几个月里都无法正常供货，急得罗永浩跑到富士康去蹲守。</p><p>发布会造起的声势，在订购用户漫长的等待中变凉了。随后3-4个月，T1逃单率从最初的2%一路飙升到接近90%。那些通过员工渠道才搞到购买码的人也跑了，理由很简单：过去几个月，天天看锤子的负面新闻看怕了。</p><p>罗永浩扛到10月，不得不宣布锤子降价，降幅在1000元左右。降价后，最便宜的16G 3G版售价1980元。</p><p>这又激怒了不少锤粉。5个月前，老罗说“我特别反感有的手机厂商在新品上市时定一个高价，之后很快又会降价的做法”，他降价的唯一可能是：新一代产品上市，前一代需要清理库存。为了显得有信服力，他还撂下狠话：如果低于2500，我是你孙子。</p><p><strong>最终，T1在2014年的总销量是25万多台。那年，中国智能手机出货量为4.207亿台，其中，小米出货量为6112万台。</strong></p><p>这样的结果无疑是让人沮丧的。罗永浩认为自己的口无遮拦把企业连累了。</p><p>那年12月，他在北展做了最后一场个人演讲《一个理想主义者的创业故事》，现场哽咽鞠躬，表示要认真学做企业家，并宣布个人微博号密码交给了公司公关部，将来所说的每一句话，要经过公司审核过再发布。</p><p>自此，“罗永浩可爱多”的微博昵称消失了。</p><p><strong>叁</strong></p><p>事实证明，罗永浩选择低姿态进入2015年，实在是个明智的选择。</p><p>那年手机行业的主题是：无人幸免。</p><p>险象在2014年已经初显。工信部监测报告显示，2014年前10个月智能手机出货量同比降幅达到10.4%，其中，国产手机出货量共2.86亿部，同比下降25.4%。显然，这是一个日趋饱和的市场。</p><p>于是，<strong>对于赶在风口成立的小手机厂商，2015年就是死亡谷。头一年还连发三款手机的大可乐在这年保持了寂静，次年三月宣布破产。</strong></p><p>行业不景气之下，上游企业随之受到牵连，珠三角多家手机代工厂出现倒闭、老板跳楼等悲剧。</p><p>大公司的日子也不好过，随着增速放缓，唱衰小米的声音此起彼伏。</p><p>那年年初，华为的余承东判断局势之残酷：未来3-5年国内只剩下三大手机厂商。当然，他不忘给自己打气，“其中就包括华为”。这位靠P6一战成名的CEO 曾经自嘲是华为的CHO（首席吹牛官）——“我学会了吹牛、打赌和应付口水战。”</p><p>8月，联想的杨元庆也在微博中写道：联想此刻正面临着严峻的挑战。头一年，联想以29.1亿美元收购摩托诺拉手机品牌，直接导致了2015年Q1财报里的2.92亿美元亏损。从后面的故事来看，此举也未能阻止联想手机业务的颓势。</p><p>如此局势之下，锤子的日子也不好过。</p><p><strong>那年锤子先后发布了坚果手机和T2，都没能打出翻身仗。最终，锤子科技在2015年亏损了4.62亿。</strong></p><p>钱成了大问题。天生骄傲的情怀在现实面前似乎不堪一击。到2016年，锤子对外公布的融资仅有AB两轮，融资金额最高的也就是2014年4月那笔1.8亿元人民币。于是，当锤子在2016年发不出工资时，罗永浩只能编了个理由：银行系统出了问题，过几天再发。</p><p>一年后，当危机化解，罗永浩把此事当做段子在极客公园大会上分享，逗得台下观众哈哈大笑。他闭口未谈期间的辛酸，包括为了钱去找小米谈收购、跟阿里质押股权，最后都没成，不得已，他跑到得到开专栏，去陌陌做直播，“卖身”换钱。</p><p>后来他说：<strong>真正的猛男，敢于直视惨淡的人生。猛男另一个特征，哭的时候要躲起来。</strong></p><p>期间也有援手。锤子科技早期投资人、紫辉创投创始合伙人郑刚称，在锤子资金危机中，贾跃亭曾经借给罗永浩1个亿。贾跃亭在2015年开始做手机，一度计划投资锤子，但考虑到交易需要时间，锤子又急需用钱，最后在没有质押股权的情况下，直接借出1个亿。</p><p>后来罗永浩用一组数据复盘了2016年：被传倒闭6次，被传收购5次，被曝资金链困境3次，被用户起诉1次。</p><p>类似的滋味雷军在这一年也品尝到了。小米在2015年开始遭遇出货量和市场份额双跌，到2016年春节时，雷军宣布取消KPI，随后，补课成为这一年的主题，他请回了黎万强，整顿供应链，找明星代言，布局线下和海外。</p><p><strong>两家公司的体量相差迥异，但在生死攸关之时，活下去的欲望足以让他们放下过往，甚至引入自己曾经鄙夷的模式。毕竟，在生意场上，生存就是最大的挑战。</strong></p><p>他们都熬出来了。</p><p>2017年，小米出货量重回世界前五，IPO 进入流程。罗永浩也宣布锤子获得新一轮10亿融资。令人意外的是，其中6亿来自成都市政府。</p><p>也是在这一年，锤子总部搬迁至成都，坚果Pro发布——这款中端机型是锤子首款产量过百万的产品。当罗永浩在发布会上哽咽：如果将来傻*都在用锤子手机，你们一定要记得，这手机是为你们做的，你似乎又能看到他昔日狂妄又感性的影子。</p><p><strong>肆</strong></p><p>做高性价比手机、出空气净化器、布局生态链……锤子幸存之后的诸多举动被业内评价：越来越像小米。</p><p>事实上，自从办完2014年那场最后的个人演讲，罗永浩就在努力把自己变成正常的企业家，把锤子变成正常的公司。去年8月宣布那笔10亿融资时，他笑眯眯地谈到：</p><p>“没意外的话，从秋天开始，我们手里会有大约 19 个亿的运作现金。这意味着我们从明年开始会像一个正规的手机厂商一样，以高、中、低三个段位，每年推出 5~6 款产品。”</p><p>言语间全然不见当年愤怒、自傲、聛睨一切的姿态。</p><p>而正是这些特质，当初让很多追随“罗胖”的粉丝变身锤粉。<strong>作为好友的冯唐曾经分析过，为什么锤子的开局那么糟糕却没有夭折，其中一个重要理由恐怕就是粉丝，“换另一个疯子和偏执狂去做，没有老罗的粉丝群，可能一年都活不下去。”</strong></p><p>在不同的锤粉看来，锤子的六年有着不同的意味。</p><p>有人为这家公司熬过难关挺到现在而开心，即使中间有过口碑糟糕的M系列手机，塑料手感让他们不敢相信“这是老罗的审美”；有人已经转身离去，因为老罗曾经的骄傲不复存在，锤子已经成为泯然众人的大路货。</p><p>比如坚果Pro ，这款定价在1499、1799、2299 的手机，出货量是锤子科技过去五年所有手机产品的总和。</p><p>这是属于商业的成功，但文艺青年们更在乎直观感受。知乎用户 Slender Man 这样写道：</p><p><strong>“一个公司需要在第三方购物网站上刷评论，一个公司需要大费笔墨来夸赞作为手机配件的钢化膜，一个公司在类似于‘虚拟来电’这样的不实用功能上吹嘘所谓工匠精神而不是改善被人诟病依旧的系统时，这大概就是对‘情怀’最大的玷污。”</strong></p><p>但熬过生死关头的罗永浩显然已经超越了这些。他在去年感慨，“你知道我这5年是怎么挺过来的吗？每次就是厚着脸皮再坚持一下。”</p><p>他的变化显而易见。</p><p>他鲜少露面，曾经那些标签，比如彪悍、情怀、工匠精神，也不再一遍遍被强化。在与罗振宇那场8个半小时的《长谈》中，他谈到自己很庆幸，因为现在不需要用讲故事来融资了，“他们（投资人）不用看我罗永浩怎么样，我也不想和他们谈，大家直接看业绩”。</p><p>他开始理解很多以前看不上的行为。“过去，我要是在机场看到一个衣冠楚楚的家伙拿着一本《赢：韦尔奇一生的管理智慧》，就会觉得这个笨蛋没救了，但现在我也会拿着这样的书硬着头皮读完。”</p><p>而4月9日北工大的这场发布会上，罗永浩的表现也越发像一位成熟的商人。</p><p>他意外地只迟到了5分钟，随后用1个小时匆匆展示了千元机坚果3；</p><p>他否定了自己以前一些过于偏执的说法——谈到“为何整天发平价机”时，他说：“设计很重要，但它只是一部分……漂亮很重要，但科技行业漂亮也没那么必要。”</p><p>在这场可能是锤子有史以来最冷清的发布会上，他也老老实实解释了坚果3此时推出的理由：在做旗舰机产品的路上走得非常艰难，不得不做中档的产品，更高性价比的产品。</p><p>只有在谈到5月15日将在鸟巢举办的那场发布会时，罗永浩又显得很兴奋。</p><p>他喜欢用“尿裤子”这个粗俗的词语形容好产品带来的震撼，于是，那天下午他说道：我曾经想过，给每一个入场（鸟巢）的人发一个纸尿裤。</p><p>在这样天马行空的瞬间，企业家罗永浩，似乎又跟那个满身是刺却内心脆弱的老罗重逢了。</p><p><strong>这是属于幸存者的幸福瞬间，即使罗永浩为此付出了“杀死老罗”的代价。但商业就是如此，正如他那天下午感慨的——科技行业没有百年老店的。“只要你干不过别人，无论有什么理由，都是没什么用的。”</strong></p><p><br/></p>', '', '', '', 255, 1, 0, 0, 5, '2018-04-12 10:06:22', '2018-04-12 10:08:03', '2018-04-13 09:36:25'),
((SELECT "id" FROM plugin_cms_category WHERE "code"='4'), '“站得稳”才“靠得住”（思想纵横）', '', 'cms-7', '习近平总书记强调：“任何时候任何情况下，党的领导干部在政治上都要站得稳、靠得住”。“站得稳”和“靠得住”，是党员领导干部至关重要的能力素养。“站得稳”，才能在复杂环境中保持冷静、坚定立场，有效应对压力和挑战，蹄疾步稳、扎扎实实做好各项工作；“靠得住”，才能凝心聚力，赢得党和人民的信任，有效发挥“', '', 'admin', '本站', '&lt;p style=&quot;box-sizing: border-box; margin: 10px auto; padding: 0px; -webkit-tap-highlight-color: transparent; color: rgb(51, 51, 51); white-space: normal; outline: 0px; border: 0px; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-stretch: normal; font-size: 18px; line-height: 36px; font-family: 微软雅黑; background-color: rgb(255, 255, 255);&quot;&gt;&lt;span style=&quot;box-sizing: border-box; font-size: 16px;&quot;&gt;&lt;span style=&quot;color: #333333; font-family: 微软雅黑; font-size: 16px; background-color: #FFFFFF;&quot;&gt;　　&lt;/span&gt;习近平总书记强调：“任何时候任何情况下，党的领导干部在政治上都要站得稳、靠得住”。“站得稳”和“靠得住”，是党员领导干部至关重要的能力素养。“站得稳”，才能在复杂环境中保持冷静、坚定立场，有效应对压力和挑战，蹄疾步稳、扎扎实实做好各项工作；“靠得住”，才能凝心聚力，赢得党和人民的信任，有效发挥“头雁效应”，团结带领大家同心同德干事业。&lt;/span&gt;&lt;/p&gt;&lt;p style=&quot;box-sizing: border-box; margin: 10px auto; padding: 0px; -webkit-tap-highlight-color: transparent; color: rgb(51, 51, 51); white-space: normal; outline: 0px; border: 0px; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-stretch: normal; font-size: 18px; line-height: 36px; font-family: 微软雅黑; background-color: rgb(255, 255, 255);&quot;&gt;&lt;span style=&quot;box-sizing: border-box; font-size: 16px;&quot;&gt;　　在工作中，“站得稳”具体表现为一种扎实稳当的工作作风。党员领导干部“站得稳”，才能做到每临大事有静气，时刻保持清醒头脑，有主见、有定力。“靠得住”，体现能力和品质。党员领导干部“靠得住”，才能在平淡无奇中不消沉，在狂风骤雨前不畏缩，在鲜花掌声中不迷失，始终保持昂扬向上干事创业的精气神。&lt;/span&gt;&lt;/p&gt;&lt;p style=&quot;box-sizing: border-box; margin: 10px auto; padding: 0px; -webkit-tap-highlight-color: transparent; color: rgb(51, 51, 51); white-space: normal; outline: 0px; border: 0px; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-stretch: normal; font-size: 18px; line-height: 36px; font-family: 微软雅黑; background-color: rgb(255, 255, 255);&quot;&gt;&lt;span style=&quot;box-sizing: border-box; font-size: 16px;&quot;&gt;　　“站得稳”与“靠得住”，二者相互依存、相互强化、辩证统一。“站得稳”为“靠得住”筑基固本，“靠得住”为“站得稳”保驾护航。“站得稳”，需要具备坚定理想信念、高尚思想境界、过硬工作能力、坚强党性原则和丰富经验积累。这样，才能在重大风险考验前面不改色，当泰山压顶时敢于担当，面对各种诱惑不为所动，在关键时刻让党信得过、让群众有主心骨。对于党员领导干部而言，“靠得住”是政治品格、政治品质的试金石。只有“靠得住”，才能担当起应该担当的责任，遇到急难险重任务不推诿、不逃避，面对群众急难愁盼，既以“等不起”的紧迫感用心用力把急事难事办妥，又以“放不下”的责任感把关系群众切身利益的事办实办好。&lt;/span&gt;&lt;/p&gt;&lt;p style=&quot;box-sizing: border-box; margin: 10px auto; padding: 0px; -webkit-tap-highlight-color: transparent; color: rgb(51, 51, 51); white-space: normal; outline: 0px; border: 0px; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-stretch: normal; font-size: 18px; line-height: 36px; font-family: 微软雅黑; background-color: rgb(255, 255, 255);&quot;&gt;&lt;span style=&quot;box-sizing: border-box; font-size: 16px;&quot;&gt;　　“站得稳”与“靠得住”，既是能力素养，更是党性修养。党性修养强，能力素养才过硬。如果遇事只计个人得失、只为自身打算，见到歪风邪气默不作声、遇到“矛盾窝子”绕而不钻、碰到“烫手山芋”推而不接；或者政治定力不强、党性修养不够，面对“乱花渐欲迷人眼”的各种诱惑乱了心、张了口、伸了手，这样的领导干部是靠不住的，也难以站得稳、立得住。&lt;/span&gt;&lt;/p&gt;&lt;p style=&quot;box-sizing: border-box; margin: 10px auto; padding: 0px; -webkit-tap-highlight-color: transparent; color: rgb(51, 51, 51); white-space: normal; outline: 0px; border: 0px; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-stretch: normal; font-size: 18px; line-height: 36px; font-family: 微软雅黑; background-color: rgb(255, 255, 255);&quot;&gt;&lt;span style=&quot;box-sizing: border-box; font-size: 16px;&quot;&gt;　　“花繁柳密处拨得开，才是手段；风狂雨急时立得定，方见脚根。”“站得稳”与“靠得住”并不是自然形成的，而是在实践中不断锻造出来的。党员领导干部只有筑牢信仰之基、补足精神之钙、把稳思想之舵，面对精心设计的“围猎”陷阱、拉拢腐蚀，确保政治上不生锈、不褪色、不变质、不变味；在时间紧、任务重、压力大时不逃避、不退缩，在摸爬滚打中提升能力本领；面对盘根错节、掰扯不清、争执不休的矛盾问题不推诿甩锅，在条分缕析中磨炼心性；在滴水穿石、愚公移山式的历史性工程中不骄不躁，一锤一锤钉钉子，一代一代接力干，才是真正“站得稳”“靠得住”。&lt;/span&gt;&lt;/p&gt;&lt;p style=&quot;box-sizing: border-box; margin: 10px auto; padding: 0px; -webkit-tap-highlight-color: transparent; color: rgb(51, 51, 51); white-space: normal; outline: 0px; border: 0px; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-stretch: normal; font-size: 18px; line-height: 36px; font-family: 微软雅黑; background-color: rgb(255, 255, 255);&quot;&gt;&lt;span style=&quot;box-sizing: border-box; font-size: 16px;&quot;&gt;　　做到“站得稳”与“靠得住”，不在一时一事而在一生一世，需要坚持不懈、久久为功。习近平总书记指出：“干部的党性修养、道德水平，不会随着党龄工龄的增长而自然提高，也不会随着职务的升迁而自然提高，必须强化自我修炼、自我约束、自我改造。”现实中，有的年轻干部刚上任就落马，也有的领导干部刚退休就身陷囹圄，其中一个重要原因在于放松了思想改造，站偏了、靠歪了。只有不断进行自我检视、剖析、反思，不断去杂质、除病毒、防污染，才能真正立得正、站得稳、走得远、靠得住。&lt;/span&gt;&lt;/p&gt;&lt;p&gt;&lt;br/&gt;&lt;/p&gt;', '', '', '习近平总书记强调：“任何时候任何情况下，党的领导干部在政治上都要站得稳、靠得住”。“站得稳”和“靠得住”，是党员领导干部至关重要的能力素养。“站得稳”，才能在复杂环境中保持冷静、坚定立场，有效应对压力和挑战，蹄疾步稳、扎扎实实做好各项工作；“靠得住”，才能凝心聚力，赢得党和人民的信任，有效发挥“', 255, 1, 0, 0, 40, '2018-04-12 10:08:50', '2018-04-12 10:09:37', '2026-04-18 21:58:25'),
((SELECT "id" FROM plugin_cms_category WHERE "code"='12'), '建设背景', '', 'cms-18', '习近平总书记强调：“任何时候任何情况下，党的领导干部在政治上都要站得稳、靠得住”。“站得稳”和“靠得住”，是党员领导干部至关重要的能力素养。“站得稳”，才能在复杂环境中保持冷静、坚定立场，有效应对压力和挑战，蹄疾步稳、扎扎实实做好各项工作；“靠得住”，才能凝心聚力，赢得党和人民的信任，有效发挥“', '', '超级管理员', '本站', '&lt;p style=&quot;box-sizing: border-box; margin: 10px auto; padding: 0px; -webkit-tap-highlight-color: transparent; color: rgb(51, 51, 51); white-space: normal; outline: 0px; border: 0px; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-stretch: normal; font-size: 18px; line-height: 36px; font-family: 微软雅黑; background-color: rgb(255, 255, 255);&quot;&gt;&lt;span style=&quot;box-sizing: border-box; font-size: 16px;&quot;&gt;　　习近平总书记强调：“任何时候任何情况下，党的领导干部在政治上都要站得稳、靠得住”。“站得稳”和“靠得住”，是党员领导干部至关重要的能力素养。“站得稳”，才能在复杂环境中保持冷静、坚定立场，有效应对压力和挑战，蹄疾步稳、扎扎实实做好各项工作；“靠得住”，才能凝心聚力，赢得党和人民的信任，有效发挥“头雁效应”，团结带领大家同心同德干事业。&lt;/span&gt;&lt;/p&gt;&lt;p style=&quot;box-sizing: border-box; margin: 10px auto; padding: 0px; -webkit-tap-highlight-color: transparent; color: rgb(51, 51, 51); white-space: normal; outline: 0px; border: 0px; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-stretch: normal; font-size: 18px; line-height: 36px; font-family: 微软雅黑; background-color: rgb(255, 255, 255);&quot;&gt;&lt;span style=&quot;box-sizing: border-box; font-size: 16px;&quot;&gt;　　在工作中，“站得稳”具体表现为一种扎实稳当的工作作风。党员领导干部“站得稳”，才能做到每临大事有静气，时刻保持清醒头脑，有主见、有定力。“靠得住”，体现能力和品质。党员领导干部“靠得住”，才能在平淡无奇中不消沉，在狂风骤雨前不畏缩，在鲜花掌声中不迷失，始终保持昂扬向上干事创业的精气神。&lt;/span&gt;&lt;/p&gt;&lt;p style=&quot;box-sizing: border-box; margin: 10px auto; padding: 0px; -webkit-tap-highlight-color: transparent; color: rgb(51, 51, 51); white-space: normal; outline: 0px; border: 0px; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-stretch: normal; font-size: 18px; line-height: 36px; font-family: 微软雅黑; background-color: rgb(255, 255, 255);&quot;&gt;&lt;span style=&quot;box-sizing: border-box; font-size: 16px;&quot;&gt;　　“站得稳”与“靠得住”，二者相互依存、相互强化、辩证统一。“站得稳”为“靠得住”筑基固本，“靠得住”为“站得稳”保驾护航。“站得稳”，需要具备坚定理想信念、高尚思想境界、过硬工作能力、坚强党性原则和丰富经验积累。这样，才能在重大风险考验前面不改色，当泰山压顶时敢于担当，面对各种诱惑不为所动，在关键时刻让党信得过、让群众有主心骨。对于党员领导干部而言，“靠得住”是政治品格、政治品质的试金石。只有“靠得住”，才能担当起应该担当的责任，遇到急难险重任务不推诿、不逃避，面对群众急难愁盼，既以“等不起”的紧迫感用心用力把急事难事办妥，又以“放不下”的责任感把关系群众切身利益的事办实办好。&lt;/span&gt;&lt;/p&gt;&lt;p style=&quot;box-sizing: border-box; margin: 10px auto; padding: 0px; -webkit-tap-highlight-color: transparent; color: rgb(51, 51, 51); white-space: normal; outline: 0px; border: 0px; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-stretch: normal; font-size: 18px; line-height: 36px; font-family: 微软雅黑; background-color: rgb(255, 255, 255);&quot;&gt;&lt;span style=&quot;box-sizing: border-box; font-size: 16px;&quot;&gt;　　“站得稳”与“靠得住”，既是能力素养，更是党性修养。党性修养强，能力素养才过硬。如果遇事只计个人得失、只为自身打算，见到歪风邪气默不作声、遇到“矛盾窝子”绕而不钻、碰到“烫手山芋”推而不接；或者政治定力不强、党性修养不够，面对“乱花渐欲迷人眼”的各种诱惑乱了心、张了口、伸了手，这样的领导干部是靠不住的，也难以站得稳、立得住。&lt;/span&gt;&lt;/p&gt;&lt;p style=&quot;box-sizing: border-box; margin: 10px auto; padding: 0px; -webkit-tap-highlight-color: transparent; color: rgb(51, 51, 51); white-space: normal; outline: 0px; border: 0px; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-stretch: normal; font-size: 18px; line-height: 36px; font-family: 微软雅黑; background-color: rgb(255, 255, 255);&quot;&gt;&lt;span style=&quot;box-sizing: border-box; font-size: 16px;&quot;&gt;　　“花繁柳密处拨得开，才是手段；风狂雨急时立得定，方见脚根。”“站得稳”与“靠得住”并不是自然形成的，而是在实践中不断锻造出来的。党员领导干部只有筑牢信仰之基、补足精神之钙、把稳思想之舵，面对精心设计的“围猎”陷阱、拉拢腐蚀，确保政治上不生锈、不褪色、不变质、不变味；在时间紧、任务重、压力大时不逃避、不退缩，在摸爬滚打中提升能力本领；面对盘根错节、掰扯不清、争执不休的矛盾问题不推诿甩锅，在条分缕析中磨炼心性；在滴水穿石、愚公移山式的历史性工程中不骄不躁，一锤一锤钉钉子，一代一代接力干，才是真正“站得稳”“靠得住”。&lt;/span&gt;&lt;/p&gt;&lt;p style=&quot;box-sizing: border-box; margin: 10px auto; padding: 0px; -webkit-tap-highlight-color: transparent; color: rgb(51, 51, 51); white-space: normal; outline: 0px; border: 0px; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-stretch: normal; font-size: 18px; line-height: 36px; font-family: 微软雅黑; background-color: rgb(255, 255, 255);&quot;&gt;&lt;span style=&quot;box-sizing: border-box; font-size: 16px;&quot;&gt;　　做到“站得稳”与“靠得住”，不在一时一事而在一生一世，需要坚持不懈、久久为功。习近平总书记指出：“干部的党性修养、道德水平，不会随着党龄工龄的增长而自然提高，也不会随着职务的升迁而自然提高，必须强化自我修炼、自我约束、自我改造。”现实中，有的年轻干部刚上任就落马，也有的领导干部刚退休就身陷囹圄，其中一个重要原因在于放松了思想改造，站偏了、靠歪了。只有不断进行自我检视、剖析、反思，不断去杂质、除病毒、防污染，才能真正立得正、站得稳、走得远、靠得住。&lt;/span&gt;&lt;/p&gt;&lt;p&gt;&lt;br/&gt;&lt;/p&gt;', '', '', '习近平总书记强调：“任何时候任何情况下，党的领导干部在政治上都要站得稳、靠得住”。“站得稳”和“靠得住”，是党员领导干部至关重要的能力素养。“站得稳”，才能在复杂环境中保持冷静、坚定立场，有效应对压力和挑战，蹄疾步稳、扎扎实实做好各项工作；“靠得住”，才能凝心聚力，赢得党和人民的信任，有效发挥“', 255, 1, 0, 0, 34, '2026-04-16 16:56:52', '2026-04-16 16:56:52', '2026-04-18 21:59:20'),
